import type { SocietyRules } from '../../src/shared/rulepack';

const names = (list: string[]) => list;

/**
 * Rules for the people of a world, invented for the tests. The tables are short and the figures
 * made up; none of it is taken from a rulebook.
 */
export function testSocietyRules(): SocietyRules {
  return {
    concentration: ['Everywhere', 'Scattered', 'Clustered', 'Gathered', 'One place'].map((name, code) => ({ max: code === 4 ? 99 : code * 2, code, name })),
    urbanisation: [{ max: 4, pct: '1D x 3' }, { max: 8, pct: '30 + 1D x 5' }, { max: 99, pct: '80 + 1D x 3' }],
    urbanLimits: [{ when: 'tl <= 3', most: '25' }, { when: 'pop >= 9', least: '40' }],
    centralisation: [{ max: 6, code: 'L', name: 'Loose', flag: 'loose' }, { max: 99, code: 'T', name: 'Tight', flag: 'tight' }],
    authority: [{ max: 5, code: 'A', name: 'Assembly' }, { max: 7, code: 'S', name: 'Shared', flag: 'shared' }, { max: 9, code: 'C', name: 'Court', flag: 'courtRules' }, { max: 99, code: 'H', name: 'Head' }],
    functions: [{ code: 'A', name: 'Assembly', flag: 'assembly' }, { code: 'H', name: 'Head' }, { code: 'C', name: 'Court' }],
    structure: [{ max: 4, code: 'e', name: 'Everyone' }, { max: 8, code: 'c', name: 'A council', sole: true }, { max: 99, code: 'o', name: 'One person', sole: true }],
    structureRules: [
      { when: 'gov == 1 and authoritative', code: 'e' },
      { when: 'gov >= 8', roll: '1D', rows: [{ max: 4, code: 'o' }, { max: 99, code: 'c' }] },
      { when: 'gov == 5', dm: 3 },
    ],
    strength: [{ max: 5, code: 'w', name: 'Weak' }, { max: 9, code: 'm', name: 'Middling' }, { max: 99, code: 's', name: 'Strong' }],
    relations: ['Friends', 'Rivals', 'Enemies', 'At war'].map((name, code) => ({ max: code === 3 ? 99 : code * 2 + 1, code, name })),
    justice: [{ max: 6, code: 'B', name: 'By the book', flag: 'byTheBook' }, { max: 9, code: 'D', name: 'By debate', flag: 'byDebate' }, { max: 99, code: 'C', name: 'By custom' }],
    uniformity: [{ max: 2, code: 'w', name: 'By who you are' }, { max: 4, code: 'p', name: 'By place' }, { max: 99, code: 'a', name: 'For all alike' }],
    uniformityRules: [{ when: 'loose', code: 'p' }],
    lawParts: [{ id: 'arms', name: 'Arms', dm: 'lawArms' }, { id: 'trade', name: 'Trade', dm: 'lawTrade' }, { id: 'speech', name: 'Speech', dm: 'lawSpeech' }],
    lawEffects: { arms: names(['Anything goes', 'No cannon', 'No guns', 'No blades', 'Nothing at all']), trade: names(['Free', 'Licensed', 'Watched', 'Run by the state']), speech: names(['Free', 'Guarded', 'Silenced']) },
    techModifier: [-2, -1, -1, 0, 0, 0, 0, 0, 1, 1, 2],
    minimumTech: [{ when: 'atm <= 1', tl: 7 }, { when: 'atm >= 4', tl: 6 }, { when: 'hab >= 0 and hab <= 2', tl: 5 }],
    tech: [
      { id: 'low', name: 'Everyday', from: 'high', least: 'high / 2', most: 'high', dm: 'techLow' },
      { id: 'power', name: 'Power', from: 'high', least: 'high - 3', most: 'high + 1', dm: 'techPower' },
      { id: 'craft', name: 'Craft', from: 'power', least: 'power - 2', most: 'power', dm: 'techCraft' },
      { id: 'flight', name: 'Flight', from: 'craft', least: '0', most: 'craft', dm: 'techFlight', zeroWhen: 'atm == 0 and tl <= 4' },
      { id: 'arms', name: 'Arms', from: 'craft', least: 'craft x (armsLaw == 0)', most: 'power', dm: 'techArms' },
    ],
    techSteps: { power: names(['Muscle', 'Wind', 'Steam', 'Sparks', 'Engines', 'Atoms', 'Suns']), craft: names(['Hands', 'Workshops', 'Mills', 'Lines', 'Robots']) },
    culture: [
      { id: 'openness', name: 'Openness', low: 'Closed', high: 'Open' },
      { id: 'zeal', name: 'Zeal', low: 'Easy-going', high: 'Fervent' },
      { id: 'thrift', name: 'Thrift', low: 'Lavish', high: 'Frugal' },
    ],
    portModifier: { A: 1.4, B: 1.2, C: 1, D: 0.8, E: 0.6, X: 0.3 },
    governmentModifier: Array.from({ length: 16 }, (_, code) => 0.7 + (code % 5) * 0.15),
    tradeModifier: { Ag: 0.9, In: 1.2, Ri: 1.3, Po: 0.7 },
    wtnPort: [{ max: 4, mods: { A: 2, B: 1, C: 1, D: 0, E: 0, X: -2 } }, { max: 99, mods: { A: 1, B: 0, C: -1, D: -2, E: -3, X: -6 } }],
    tariffs: [{ max: 4, name: 'None' }, { max: 6, name: 'On luxuries only', again: true }, { max: 9, name: 'Light', rate: '1D' }, { max: 99, name: 'Heavy', rate: '2D x 4' }],
    highport: { A: 7, B: 9, C: 11 },
    traffic: [{ least: 3, name: 'Busy', daily: '2D + 6', weekly: 100 }, { least: 0, name: 'Steady', daily: '1D - 1', weekly: 15 }, { least: -99, name: 'Quiet', daily: '1D - 4', weekly: 2 }],
    spaceports: [{ max: 2, code: 'Z', name: 'Nothing' }, { max: 4, code: 'P', name: 'A pad' }, { max: 99, code: 'Q', name: 'A proper field' }],
    secondaryGovernment: [{ max: 2, gov: 0 }, { max: 4, gov: 1 }, { max: 99, gov: 6 }],
    classes: [
      { code: 'Ou', name: 'Outpost', when: 'pop <= 2' },
      { code: 'Fm', name: 'Farm', when: 'inZone and atm >= 2 and atm <= 3 and pop >= 2' },
      { code: 'Pi', name: 'Pit', when: 'mainIn and pop >= 2', on: '2D >= 8 - 3 x belt', flag: 'pit' },
      { code: 'Ft', name: 'Fort', when: 'mainTl >= 7 and gov == 6', on: '2D + 2 x (mainBases > 0) >= 9', flag: 'fort' },
      { code: 'Fr', name: 'Free town', when: 'gov <= 1 and mainTl >= 7', on: '2D >= 10', flag: 'freeport' },
    ],
    captiveLaw: [{ max: 3, f: 'mainLaw' }, { max: 99, f: 'mainLaw + D3' }],
    dm: {
      concentration: [{ when: 'size <= 3', dm: 2 }, { when: 'pop >= 8', dm: -2 }, { when: 'minTl >= 6', dm: 3 }, { when: 'Ag', dm: -2 }],
      urbanisation: [{ when: 'pcr >= 3', dm: 1, times: 'pcr - 2' }, { when: 'tl >= 8', dm: 2 }, { when: 'Ag', dm: -3 }],
      centralisation: [{ when: 'gov >= 8', dm: 2 }, { when: 'balkanised', dm: 1 }, { when: 'pcr <= 1', dm: -2 }],
      authority: [{ when: 'gov >= 10', dm: 4 }, { when: 'gov <= 2', dm: -3 }, { when: 'tight', dm: 1 }],
      factions: [{ when: 'gov == 0 or balkanised', dm: 1 }, { when: 'gov >= 12', dm: -1 }],
      relations: [{ when: 'withRulers', dm: 1 }, { when: 'sameGovernment', dm: -2 }],
      justice: [{ when: 'gov >= 12', dm: 3 }, { when: 'courtRules', dm: -2 }, { when: 'tl <= 2', dm: 3 }],
      uniformity: [{ when: 'gov >= 10', dm: -1 }],
      presumption: [{ when: '1', dm: -1, times: 'law' }, { when: 'byDebate', dm: 3 }],
      death: [{ when: 'law >= 8', dm: 3 }, { when: 'gov == 0', dm: -3 }],
      lawArms: [{ when: 'pcr >= 3', dm: 1 }],
      lawTrade: [{ when: 'gov == 1', dm: 2 }],
      lawSpeech: [{ when: 'gov >= 12', dm: 2 }, { when: 'gov <= 2', dm: -1 }],
      techLow: [{ when: 'pop >= 9', dm: -1 }, { when: 'balkanised', dm: -1 }],
      techPower: [{ when: 'In', dm: 1 }],
      techCraft: [{ when: 'pop <= 4', dm: -1 }, { when: 'In', dm: 1 }],
      techFlight: [{ when: 'atm <= 1', dm: -2 }],
      techArms: [{ when: 'law >= 9', dm: 1 }, { when: 'balkanised', dm: 2 }],
      openness: [{ when: 'portA or portB', dm: 2 }, { when: 'portX', dm: -4 }, { when: 'law >= 9', dm: -2 }],
      zeal: [{ when: 'gov >= 12', dm: 3 }, { when: 'openness >= 9', dm: -2 }, { when: 'openness <= 4', dm: 2 }],
      thrift: [{ when: 'Po', dm: 3 }, { when: 'Ri', dm: -3 }, { when: 'zeal >= 9', dm: 1 }],
      importance: [{ when: 'portA or portB', dm: 1 }, { when: 'portE or portX', dm: -1 }, { when: 'pop >= 8', dm: 1 }, { when: 'pop <= 4', dm: -1 }, { when: 'tl >= 10', dm: 1 }, { when: 'bases >= 1', dm: 1 }, { when: 'In or Ri', dm: 1 }],
      efficiency: [{ when: 'gov <= 4', dm: 1 }, { when: 'gov >= 10', dm: -1 }, { when: 'zeal >= 9', dm: -1 }, { when: 'thrift >= 9', dm: 1 }],
      wtn: [{ when: 'tl >= 8', dm: 1 }, { when: 'tl <= 3', dm: -1 }],
      inequality: [{ when: 'gov >= 10', dm: 8 }, { when: 'gov == 2', dm: -8 }, { when: '1', dm: 2, times: 'pcr' }, { when: '1', dm: -1, times: 'infrastructure' }],
      tariffs: [{ when: 'gov == 0', dm: -5 }, { when: 'openness <= 4', dm: 2 }, { when: 'openness >= 9', dm: -2 }, { when: 'freeport', dm: -5 }, { when: '1', dm: -1, times: 'wtnPort' }],
      highport: [{ when: 'pop >= 8', dm: 1 }, { when: 'tl >= 10', dm: 2 }],
      spaceport: [{ when: 'pop >= 4', dm: 2 }, { when: 'pop <= 1', dm: -1 }],
      secondaryGovernment: [{ when: 'mainGov == 0', dm: -2 }, { when: 'mainGov >= 10', dm: 2 }],
      captiveLaw: [{ when: 'fort', dm: 1 }],
    },
    f: {
      populationDigit: 'D3 x 3',
      populationMore: 'd10 - 1',
      'concentration.onePlaceBelow': 5,
      'concentration.onePlace': '1D > pop',
      'concentration.all': 4,
      concentration: '1D + DM',
      'concentration.leastFrom': 9,
      urbanisation: '2D + DM',
      'cities.few': 'min(4 - pcr, pop)',
      'cities.one': 'max(1, pop - 1D - 3)',
      cities: 'max(1, ceil(1D + urban / 10 - pcr))',
      'cities.people': 'pcr / (D3 + 3)',
      'cities.smallBelow': 5,
      'cities.listed': 4,
      'city.share': '(D3 + 3) x 10',
      'city.chunks': 'D3',
      'town.largest': 'min(urbanPeople / 50, 1D x 2000)',
      government: '2D - 6 + pop',
      'government.most': 15,
      'government.balkanised': 7,
      'government.none': 0,
      centralisation: '2D + DM',
      authority: '2D + DM',
      structure: '2D + DM',
      factions: 'D3 + DM',
      'factions.most': 4,
      nations: 'D3 + 1',
      strength: '2D',
      relation: '1D + DM',
      justice: '2D + DM',
      'justice.economic': '2D + law >= 14',
      uniformity: '1D + DM',
      presumption: '2D + DM >= 1',
      death: '2D + DM >= 9',
      lawPart: 'max(0, min(12, law + D3 - 2 + DM))',
      techModifier: '2D',
      'tech.ceiling': 14,
      trait: 'max(1, 2D + DM)',
      'trait.lowTo': 4,
      'trait.highFrom': 10,
      'resource.unknown': '1D + 3',
      'resource.worked': 'max(1, resources - D3 x (In or Ag))',
      resourceFactor: 'RATING + (tl >= 9) x giants',
      labourFactor: 'max(0, pop - 2)',
      infrastructureFactor: 'max(0, importance + (pop >= 5) x 1D)',
      'efficiency.small': '1D - 4 + DM',
      'efficiency.large': 'D3 - 2 + DM',
      'efficiency.largeFrom': 8,
      'efficiency.bound': 4,
      baseValue: 'max(1, max(1, infrastructure) + max(1, resource))',
      techFactor: 'max(0.1, tl / 12)',
      gwp: '800 x BASE x MODS x efficiency',
      'gwp.inefficient': '800 x BASE x MODS / (2 - efficiency)',
      wtn: 'pop + DM',
      inequality: 'max(0, min(100, 40 - efficiency x 4 + (2D - 7) + DM))',
      development: 'gwpPerHead / 1000 x (1 - inequality / 100)',
      tariff: '2D + DM',
      'tariff.again': '1D + 6',
      highport: '2D + DM',
      'secondary.cap': 'pop - D3',
      'secondary.population': 'min(CAP, 2D - 8 + floor(hab / 3) + (resources >= 8))',
      'secondary.government': '1D + DM',
      'secondary.law': '2D - 6 + gov',
      'secondary.captive': 6,
      'secondary.captiveLaw': '1D + DM',
      'secondary.tl': 'max(minTl, mainTl - 1 + (fort or pit))',
      'secondary.tl.freeport': 'max(minTl, mainTl - D3)',
      spaceport: '1D + DM',
    },
  };
}
